#include "Semestre.hpp"
#include "ValidadorAcademico.hpp"
#include "Excecoes.hpp"
#include <algorithm>
namespace semestria {
Semestre::Semestre(const std::string&i):identificador_(i){if(!ValidadorAcademico::textoValido(i))throw DadoInvalidoException("Identificador do semestre inválido.");} const std::string& Semestre::getIdentificador()const{return identificador_;}
void Semestre::adicionarDisciplina(const Disciplina& d){if(possuiDisciplina(d.getCodigo()))throw DisciplinaDuplicadaException("Disciplina já cadastrada.");for(const auto& x:disciplinas_)if(x.conflitaCom(d))throw ConflitoHorarioException("Conflito de horário entre disciplinas.");disciplinas_.push_back(d);} void Semestre::removerDisciplina(const std::string& c){for(auto i=disciplinas_.begin();i!=disciplinas_.end();++i)if(i->getCodigo()==c){disciplinas_.erase(i);return;}throw DisciplinaNaoEncontradaException("Disciplina não encontrada.");}
Disciplina& Semestre::buscarDisciplina(const std::string&c){for(auto&i:disciplinas_)if(i.getCodigo()==c)return i;throw DisciplinaNaoEncontradaException("Disciplina não encontrada.");} const Disciplina& Semestre::buscarDisciplina(const std::string&c)const{for(const auto&i:disciplinas_)if(i.getCodigo()==c)return i;throw DisciplinaNaoEncontradaException("Disciplina não encontrada.");} bool Semestre::possuiDisciplina(const std::string&c)const{for(const auto&i:disciplinas_)if(i.getCodigo()==c)return true;return false;} const std::vector<Disciplina>& Semestre::getDisciplinas()const{return disciplinas_;} std::size_t Semestre::quantidadeDisciplinas()const{return disciplinas_.size();}
void Semestre::adicionarHorario(const std::string& c,const Horario& h){Disciplina& d=buscarDisciplina(c);for(const auto& x:disciplinas_)if(x.getCodigo()!=c)for(const auto& y:x.getHorarios())if(y.colideCom(h))throw ConflitoHorarioException("Conflito de horário entre disciplinas.");d.adicionarHorario(h);}
std::vector<ConflitoHorario> Semestre::identificarConflitos()const{std::vector<ConflitoHorario> r;for(std::size_t i=0;i<disciplinas_.size();++i)for(std::size_t j=i+1;j<disciplinas_.size();++j)for(const auto&a:disciplinas_[i].getHorarios())for(const auto&b:disciplinas_[j].getHorarios())if(a.colideCom(b)){r.push_back(ConflitoHorario{disciplinas_[i].getCodigo(),disciplinas_[j].getCodigo(),a,b});}return r;}
int Semestre::totalCreditos()const{int n=0;for(const auto&d:disciplinas_)n+=d.getCreditos();return n;} int Semestre::cargaHorariaTotal()const{int n=0;for(const auto&d:disciplinas_)n+=d.getCargaHoraria();return n;}
double Semestre::calcularNSGAtual()const{if(totalCreditos()==0)return 0;double s=0;for(const auto&d:disciplinas_)s+=d.calcularNotaFinal()*d.getCreditos();return s/totalCreditos();} double Semestre::calcularNSGProjetada()const{if(totalCreditos()==0)return 0;double s=0;for(const auto&d:disciplinas_)s+=d.calcularNotaProjetada()*d.getCreditos();return s/totalCreditos();} double Semestre::calcularNSGMaxima()const{if(totalCreditos()==0)return 0;double s=0;for(const auto&d:disciplinas_)s+=d.calcularNotaMaxima()*d.getCreditos();return s/totalCreditos();}
}
